namespace sv_c3753c8ed3fc40c78214f3de9f146552.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

namespace sv_c3753c8ed3fc40c78214f3de9f146552.Services;

public class MockChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;

    public MockChatService()
    {
        _channels = new List<Channel>
        {
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering updates and discussions", 0),
            new(3, "design", "Design reviews and feedback", 5),
            new(4, "random", "Water cooler chat", 1),
            new(5, "announcements", "Important team announcements", 0),
        };

        var now = DateTime.UtcNow;
        _messages = new List<Message>
        {
            new(1, 1, "Alice", "Hey team! Welcome to the new chat app 🎉", now.AddHours(-5), null,
                new() { new("🎉", new() { "Bob", "Carol" }), new("👍", new() { "Dave" }) }),
            new(2, 1, "Bob", "Looks great! Love the new design.", now.AddHours(-4.5), null, new()),
            new(3, 1, "Carol", "Thanks Alice! Quick question — are we migrating the old messages?", now.AddHours(-4), null, new()),
            new(4, 1, "Alice", "Yes, we plan to migrate everything from the old system by next week.", now.AddHours(-3.5), 3, new()),
            new(5, 1, "Dave", "I've pushed the latest API changes. Please review when you get a chance.", now.AddHours(-3), null,
                new() { new("👀", new() { "Alice", "Bob" }) }),
            new(6, 1, "Bob", "On it! Will review this afternoon.", now.AddHours(-2.5), 5, new()),
            new(7, 1, "Carol", "Has anyone tested the notification system?", now.AddHours(-2), null, new()),
            new(8, 1, "Dave", "I tested it yesterday, works well on desktop. Mobile still needs work.", now.AddHours(-1.5), 7, new()),
            new(9, 1, "Alice", "Good catch Dave. Let's track that in the sprint board.", now.AddHours(-1.5), 7, new()),
            new(10, 1, "Alice", "Team standup in 15 minutes! 🕐", now.AddMinutes(-30), null,
                new() { new("👍", new() { "Bob", "Carol", "Dave" }) }),
            new(11, 1, "Bob", "I'll be there", now.AddMinutes(-25), null, new()),
            new(12, 1, "Carol", "Same here!", now.AddMinutes(-20), null, new()),
            new(13, 1, "Dave", "Running 5 min late, start without me", now.AddMinutes(-15), null, new()),
            new(14, 1, "Alice", "No worries Dave, see you soon", now.AddMinutes(-10), null, new()),
            new(15, 1, "Bob", "Great standup everyone. Let's keep the momentum going!", now.AddMinutes(-2), null,
                new() { new("🚀", new() { "Alice", "Carol" }) }),

            new(101, 2, "Dave", "Deployed v2.3.1 to staging. Release notes in the wiki.", now.AddHours(-6), null,
                new() { new("🚀", new() { "Alice" }) }),
            new(102, 2, "Alice", "Nice! Any breaking changes we should know about?", now.AddHours(-5.5), null, new()),
            new(103, 2, "Dave", "Just one — the auth token format changed. See migration guide.", now.AddHours(-5), 102, new()),
            new(104, 2, "Bob", "CI pipeline is green across all branches 🟢", now.AddHours(-3), null,
                new() { new("🎉", new() { "Dave", "Carol" }) }),
            new(105, 2, "Carol", "I've updated the component library. New button variants are live.", now.AddHours(-1), null, new()),

            new(201, 3, "Carol", "New mockups for the dashboard redesign are ready for review", now.AddHours(-8), null,
