@page "/chat"
@using sv_c3753c8ed3fc40c78214f3de9f146552.Services
@inject IChatService ChatService
@inject IJSRuntime JS
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    @* ── Left Sidebar: Channel List ── *@
    <aside class="chat-sidebar">
        <div class="sidebar-header">
            <h5>Channels</h5>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel.Id)">
                        <div class="channel-name"># @channel.Name</div>
                        <div class="channel-desc">@TruncateDescription(channel.Description)</div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ── Main Message Area ── *@
    <section class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_activeChannel is not null)
        {
            <div class="main-header">
                <h4># @_activeChannel.Name</h4>
                <span class="main-header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @ref="_messageListRef" @onscroll="OnMessageListScroll">
                @if (_loadingOlder)
                {
                    <div class="loading-older">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => { if (_hoveredMessageId == msg.Id) _hoveredMessageId = null; }">
                            <div class="message-bubble">
                                <div class="message-header">
                                    <span class="message-author">@msg.Author</span>
                                    <span class="message-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="message-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var reaction in msg.Reactions)
                                        {
                                            <button class="reaction-badge" @onclick="() => AddReactionAsync(msg.Id, reaction.Emoji)"
                                                    title="@string.Join(", ", reaction.Users)">
                                                @reaction.Emoji @reaction.Users.Count
                                            </button>
                                        }
                                    </div>
                                }

                                @{ var replyCount = GetReplyCount(msg.Id); }
                                @if (replyCount > 0)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        💬 @replyCount @(replyCount == 1 ? "reply" : "replies")
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread" @onclick="() => OpenThreadAsync(msg.Id)">💬</button>
                                    <button class="action-btn" title="React" @onclick="() => ToggleEmojiPicker(msg.Id)">😊</button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option" @onclick="() => AddReactionAsync(msg.Id, emoji)">@emoji</button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-textarea" @bind="_newMessageText" @bind:event="oninput"
                          placeholder="Message #@_activeChannel.Name"
                          @onkeydown="OnMessageKeyDown"></textarea>
                <button class="send-btn" @onclick="SendMessageAsync" disabled="@string.IsNullOrWhiteSpace(_newMessageText)">Send</button>
            </div>
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ── Right Panel: Thread View ── *@
    @if (_threadOpen && _threadMessages is not null)
    {
        <aside class="chat-thread-panel">
            <div class="thread-header">
                <h5>Thread</h5>
                <button class="close-thread-btn" @onclick="CloseThread" title="Close thread">✕</button>
            </div>

            @if (_threadMessages.Count > 0)
            {
                <div class="thread-root-quote">
                    <span class="message-author">@_threadMessages[0].Author</span>
                    <p>@_threadMessages[0].Content</p>
                </div>
            }

            <div class="thread-messages">
                @foreach (var reply in _threadMessages.Skip(1))
                {
                    <div class="thread-reply">
                        <div class="message-header">
                            <span class="message-author">@reply.Author</span>
                            <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                        </div>
                        <div class="message-content">@reply.Content</div>
                    </div>
                }
            </div>

            <div class="thread-input-area">
                <textarea class="message-textarea" @bind="_threadReplyText" @bind:event="oninput"
                          placeholder="Reply in thread…"
                          @onkeydown="OnThreadKeyDown"></textarea>
                <button class="send-btn" @onclick="SendThreadReplyAsync" disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">Reply</button>
            </div>
        </aside>
